def cluster_close(points, radius=6):
    if len(points)==0:return points
    pts=np.array(points,float)
    # union find
    n=len(pts); parent=list(range(n))
    def find(a):
        while parent[a]!=a:
            parent[a]=parent[parent[a]];a=parent[a]
        return a
    def union(a,b):
        a,b=find(a),find(b)
        if a!=b:parent[b]=a
    for i in range(n):
        for j in range(i):
            if np.linalg.norm(pts[i,:2]-pts[j,:2])<=radius: union(i,j)
    out=[]
    for root in set(find(i) for i in range(n)):
        ids=[i for i in range(n) if find(i)==root]
        # weighted by dt
        best=max(ids,key=lambda i:pts[i,2])
        out.append(pts[best])
    return np.array(out)

